// Controller を MockMvc で呼んでみる(Web サーバーは起動しない)
// ここを変えてみよう:URL やクエリを書き換える / name を消す
import static java.nio.charset.StandardCharsets.UTF_8;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.converter.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;

@RestController
class HelloController {
    @GetMapping("/hello")   // GET /hello?name=...
    String hello(
            @RequestParam(defaultValue = "ゲスト") String name) {
        return "こんにちは、" + name + "さん";
    }

    @GetMapping("/users/{id}")   // GET /users/7
    String user(@PathVariable int id) {
        return "ユーザー" + id + "番";
    }

    @PostMapping("/login")   // name は必須(required = true)
    String login(@RequestParam String name) {
        return name + " でログインしました";
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        MockMvc mvc = MockMvcBuilders
                .standaloneSetup(new HelloController())
                .setMessageConverters(
                        new StringHttpMessageConverter(UTF_8))
                .defaultResponseCharacterEncoding(UTF_8)
                .build();

        send(mvc, get("/hello"));
        send(mvc, get("/hello").param("name", "ハル"));
        send(mvc, get("/users/7"));
        // int に変換できない
        send(mvc, get("/users/abc"));
        // 必須パラメータ name が無い
        send(mvc, post("/login"));
        send(mvc, post("/login").param("name", "haru"));
        // GET 専用のパスに POST
        send(mvc, post("/hello"));
        // 対応表に無いパス
        send(mvc, get("/nothing"));
    }

    static void send(MockMvc mvc, RequestBuilder req)
            throws Exception {
        MvcResult result = mvc.perform(req).andReturn();
        var request = result.getRequest();
        var res = result.getResponse();
        // 送ったパラメータを " name=値" の形で並べる
        StringBuilder params = new StringBuilder();
        request.getParameterMap().forEach((k, v) ->
                params.append(" " + k + "=" + v[0]));
        Exception ex = result.getResolvedException();
        String body = ex != null
                ? "[" + ex.getClass().getSimpleName() + "]"
                : res.getContentAsString();
        System.out.println(request.getMethod() + " "
                + request.getRequestURI() + params
                + " → " + res.getStatus() + " " + body);
    }
}

