import static java.nio.charset.StandardCharsets.UTF_8;
import java.util.Map;
import org.springframework.http.*;
import org.springframework.http.converter.*;
import org.springframework.http.converter.json.*;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;

record Item(int id, String name, int price) {}

@RestController
@RequestMapping("/api/items")   // 共通プレフィックス
class ItemApi {
    Map<Integer, Item> items = Map.of(
            1, new Item(1, "ボールペン", 120),
            2, new Item(2, "ノート", 200));

    @GetMapping("/{id}")   // GET /api/items/{id}
    ResponseEntity<Item> find(@PathVariable int id) {
        Item item = items.get(id);
        if (item == null) {
            return ResponseEntity.notFound().build(); // 404
        }
        return ResponseEntity.ok(item);   // 200 + JSON
    }
}

@Controller   // 画面用。"redirect:" で始まるとリダイレクト
class OrderController {
    long nextId = 100;

    @PostMapping("/orders")
    String order(@RequestParam int itemId,
                 @RequestParam int quantity) {
        long id = nextId++;
        System.out.println("  (注文を登録: 商品" + itemId
                + " × " + quantity + ")");
        return "redirect:/orders/" + id;   // PRG パターン
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        MockMvc mvc = MockMvcBuilders
                .standaloneSetup(new ItemApi(), new OrderController())
                .setMessageConverters(
                        new StringHttpMessageConverter(UTF_8),
                        new MappingJackson2HttpMessageConverter())
                .defaultResponseCharacterEncoding(UTF_8)
                .build();

        send(mvc, get("/api/items/1"));
        send(mvc, get("/api/items/99"));
        send(mvc, post("/orders")
                .param("itemId", "1").param("quantity", "3"));
    }

    static void send(MockMvc mvc, RequestBuilder req)
            throws Exception {
        MvcResult result = mvc.perform(req).andReturn();
        var res = result.getResponse();
        System.out.println(result.getRequest().getMethod() + " "
                + result.getRequest().getRequestURI()
                + " → " + res.getStatus());
        if (res.getHeader("Location") != null) {
            System.out.println("  Location: "
                    + res.getHeader("Location"));
        }
        String body = res.getContentAsString();
        if (!body.isEmpty()) {
            System.out.println("  " + res.getContentType());
            System.out.println("  " + body);
        }
    }
}

